acceptance_cmd:
set -eu
H=$(./ops/worktree_registry.py hand-back --help 2>&1)
claims_default=$(printf '%s' "$H" | grep -ci 'default: current worktree' || true)
if [ "$claims_default" != "0" ]; then
  printf '%s' "$H" | grep -Fq -- '--branch' || { echo "FAIL: help still claims a usable default and never mentions --branch"; exit 1; }
fi
test -f ops/tests/test_worktree_registry.sh || { echo "FAIL: no regression test file to pin this"; exit 1; }
grep -Eq 'hand-back|hand_back' ops/tests/test_worktree_registry.sh || { echo "FAIL: hand-back selector behaviour is not pinned by any test"; exit 1; }
grep -Eqi 'retry with|--branch' ops/tests/test_worktree_registry.sh || { echo "FAIL: no test pins that the refusal (or the fixed default) is actionable"; exit 1; }
echo OK
